#!/usr/bin/env node
// ~/.claude/scripts/check-deps.js
const { TOOL_INPUT, TOOL_NAME } = process.env;

try {
  const input = JSON.parse(TOOL_INPUT);
  console.log(`Tool: ${TOOL_NAME}`);
  console.log(`Input: ${JSON.stringify(input, null, 2)}`);
  process.exit(0);
} catch (e) {
  console.error('Error processing input:', e.message);
  process.exit(1);
}

