        "matcher": "Bash",
        "command": "if echo $TOOL_INPUT | jq -r '.command' | grep -q 'git commit'; then ~/.claude/scripts/pre-commit-check.sh; fi"
      }
    ]
  }
}

{
  "hooks": {
    "PreToolUse": [
